<?php
require_once __DIR__.'/../../includes/bootstrap.php';require_login();
$q=trim($_GET['q']??'');$status=$_GET['status']??'';$category=(int)($_GET['category']??0);$sql="SELECT p.*,c.name category_name,(SELECT COUNT(*) FROM page_views v WHERE v.project_id=p.id) total_views,(SELECT COUNT(*) FROM page_views v WHERE v.project_id=p.id AND v.viewed_at>=DATE_FORMAT(CURDATE(),'%Y-%m-01')) month_views FROM projects p JOIN project_categories c ON c.id=p.category_id WHERE 1=1";$args=[];if($q!==''){$sql.=' AND (p.title LIKE ? OR p.location LIKE ? OR p.city LIKE ?)';array_push($args,"%$q%","%$q%","%$q%");}if(in_array($status,['draft','published','archived'],true)){$sql.=' AND p.status=?';$args[]=$status;}if($category){$sql.=' AND p.category_id=?';$args[]=$category;}$sql.=' ORDER BY p.updated_at DESC';$s=db()->prepare($sql);$s->execute($args);$projects=$s->fetchAll();$cats=db()->query('SELECT id,name FROM project_categories ORDER BY name')->fetchAll();$pageTitle='Projects';require __DIR__.'/../../includes/admin_header.php';
?><p><a href="<?=base_url('admin/projects/add.php')?>">Add New Project</a></p><form method="get"><input name="q" value="<?=e($q)?>" placeholder="Search title or location"><select name="category"><option value="0">All categories</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=$category===$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><select name="status"><option value="">All statuses</option><?php foreach(['draft','published','archived'] as $v):?><option value="<?=$v?>" <?=$status===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select><button>Filter</button></form><table border="1" cellpadding="6"><tr><th>Project</th><th>Category</th><th>Status</th><th>Total views</th><th>This month</th><th>Featured</th><th>Actions</th></tr><?php foreach($projects as $p):?><tr><td><?=e($p['title'])?></td><td><?=e($p['category_name'])?></td><td><?=e($p['status'])?></td><td><?= (int)$p['total_views']?></td><td><?= (int)$p['month_views']?></td><td><?= $p['is_featured']?'Yes':'No'?></td><td><a href="<?=base_url('admin/projects/edit.php?id='.$p['id'])?>">Edit</a> | <a href="<?=base_url('admin/projects/revisions.php?id='.$p['id'])?>">History</a> | <a href="<?=base_url('admin/projects/seo-check.php?id='.$p['id'])?>">SEO check</a> | <form method="post" action="<?=base_url('admin/projects/archive.php')?>" style="display:inline" onsubmit="return confirm('Archive this project?')"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$p['id']?>"><button type="submit">Archive</button></form> | <a href="<?=base_url('project.php?slug='.urlencode($p['slug']))?>" target="_blank">Preview</a></td></tr><?php endforeach;?></table><?php require __DIR__.'/../../includes/admin_footer.php';
